     1	'use client';
     2	
     3	import Image from 'next/image';
     4	import Link from 'next/link';
     5	import type { Novel } from '@/types/novel';
     6	
     7	interface NovelCardProps {
     8	  novel: Novel;
     9	  className?: string;
    10	}
    11	
    12	export default function NovelCard({ novel, className = '' }: NovelCardProps) {
    13	  // 格式化数字显示
    14	  const formatNumber = (num: number): string => {
    15	    if (num >= 10000) {
    16	      return `${(num / 10000).toFixed(1)}万`;
    17	    }
    18	    return num.toString();
    19	  };
    20	
    21	  // 获取状态文本 - 直接使用后端返回的 status_text
    22	  const getStatusText = (): string => {
    23	    return novel.status_text || novel.status;
    24	  };
    25	
    26	  // 获取状态颜色
    27	  const getStatusColor = (status: Novel['status']): string => {
    28	    const colorMap = {
    29	      draft: 'text-gray-500',
    30	      serializing: 'text-green-600',
    31	      completed: 'text-blue-600',
    32	      paused: 'text-yellow-600',
    33	    };
    34	    return colorMap[status] || 'text-gray-500';
    35	  };
    36	
    37	  return (
    38	    <div className={`group ${className}`}>
    39	      <Link href={`/novel/${novel.id}`}>
    40	        <div className="bg-theme-bg-secondary border border-theme-border
    41	                        rounded-lg overflow-hidden hover:shadow-lg
    42	                        transition-theme hover:scale-[1.02]">
    43	          {/* 封面图片 */}
    44	          <div className="relative aspect-[3/4] overflow-hidden">
    45	            {novel.cover_image ? (
    46	              <Image
    47	                src={novel.cover_image}
    48	                alt={novel.title}
    49	                fill
    50	                className="object-cover group-hover:scale-105 transition-transform duration-200"
    51	                sizes="(max-width: 768px) 50vw, (max-width: 1200px) 33vw, 25vw"
    52	              />
    53	            ) : (
    54	              <div className="w-full h-full bg-light-border dark:bg-dark-border 
    55	                            flex items-center justify-center">
    56	                <svg
    57	                  className="w-12 h-12 text-light-text-secondary dark:text-dark-text-secondary"
    58	                  fill="none"
    59	                  stroke="currentColor"
    60	                  viewBox="0 0 24 24"
    61	                >
    62	                  <path
    63	                    strokeLinecap="round"
    64	                    strokeLinejoin="round"
    65	                    strokeWidth={2}
    66	                    d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.746 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"
    67	                  />
    68	                </svg>
    69	              </div>
    70	            )}
    71	            
    72	            {/* VIP 标识 */}
    73	            {novel.is_vip && (
    74	              <div className="absolute top-2 right-2 bg-yellow-500 text-white 
    75	                            px-2 py-1 rounded text-xs font-medium">
    76	                VIP
    77	              </div>
    78	            )}
    79	            
    80	            {/* 推荐标识 */}
    81	            {novel.is_recommended && (
    82	              <div className="absolute top-2 left-2 bg-red-500 text-white 
    83	                            px-2 py-1 rounded text-xs font-medium">
    84	                推荐
    85	              </div>
    86	            )}
    87	          </div>
    88	
    89	          {/* 内容区域 */}
    90	          <div className="p-4">
    91	            {/* 标题 */}
    92	            <h3 className="font-semibold text-light-text dark:text-dark-text 
    93	                         line-clamp-2 mb-2 group-hover:text-light-accent 
    94	                         dark:group-hover:text-dark-accent transition-colors">
    95	              {novel.title}
    96	            </h3>
    97	
    98	            {/* 作者 */}
    99	            <p className="text-sm text-light-text-secondary dark:text-dark-text-secondary mb-2">
   100	              作者：{novel.author}
   101	            </p>
   102	
   103	            {/* 简介 */}
   104	            <p className="text-sm text-light-text-secondary dark:text-dark-text-secondary 
   105	                         line-clamp-3 mb-3 leading-relaxed">
   106	              {novel.description}
   107	            </p>
   108	
   109	            {/* 标签 */}
   110	            {novel.tags && novel.tags.length > 0 && (
   111	              <div className="flex flex-wrap gap-1 mb-3">
   112	                {novel.tags.slice(0, 3).map((tag) => (
   113	                  <span
   114	                    key={tag.id}
   115	                    className="px-2 py-1 text-xs rounded font-medium text-white text-shadow-sm"
   116	                    style={{
   117	                      backgroundColor: tag.color || '#c49e65',
   118	                      fontSize: '10px'
   119	                    }}
   120	                  >
   121	                    {tag.name}
   122	                  </span>
   123	                ))}
   124	                {novel.tags.length > 3 && (
   125	                  <span className="px-2 py-1 text-xs text-light-text-secondary dark:text-dark-text-secondary">
   126	                    +{novel.tags.length - 3}
   127	                  </span>
   128	                )}
   129	              </div>
   130	            )}
   131	
   132	            {/* 统计信息 */}
   133	            <div className="flex items-center justify-between text-xs
   134	                          text-light-text-secondary dark:text-dark-text-secondary">
   135	              <div className="flex items-center space-x-3">
   136	                <span>{novel.word_count_formatted || `${formatNumber(novel.word_count)}字`}</span>
   137	                <span>{novel.chapter_count}章</span>
   138	                <span className={getStatusColor(novel.status)}>
   139	                  {getStatusText()}
   140	                </span>
   141	              </div>
   142	              
   143	              <div className="flex items-center space-x-2">
   144	                {/* 浏览量 */}
   145	                <div className="flex items-center space-x-1">
   146	                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
   147	                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} 
   148	                          d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
   149	                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} 
   150	                          d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
   151	                  </svg>
   152	                  <span>{formatNumber(novel.view_count)}</span>
   153	                </div>
   154	                
   155	                {/* 收藏量 */}
   156	                <div className="flex items-center space-x-1">
   157	                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
   158	                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} 
   159	                          d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
   160	                  </svg>
   161	                  <span>{formatNumber(novel.bookmark_count)}</span>
   162	                </div>
   163	              </div>
   164	            </div>
   165	
   166	            {/* 评分 */}
   167	            {parseFloat(novel.rating) > 0 && (
   168	              <div className="flex items-center mt-2 text-xs">
   169	                <div className="flex items-center space-x-1 text-yellow-500">
   170	                  {[...Array(5)].map((_, i) => (
   171	                    <svg
   172	                      key={i}
   173	                      className={`w-3 h-3 ${
   174	                        i < Math.floor(parseFloat(novel.rating)) ? 'fill-current' : 'fill-gray-300'
   175	                      }`}
   176	                      viewBox="0 0 24 24"
   177	                    >
   178	                      <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
   179	                    </svg>
   180	                  ))}
   181	                </div>
   182	                <span className="ml-1 text-light-text-secondary dark:text-dark-text-secondary">
   183	                  {novel.rating} ({formatNumber(novel.rating_count)})
   184	                </span>
   185	              </div>
   186	            )}
   187	          </div>
   188	        </div>
   189	      </Link>
   190	    </div>
   191	  );
   192	}
...
