    92	
    93	/**
    94	 * 截断文本
    95	 */
    96	export function truncateText(text: string, maxLength: number): string {
    97	  if (text.length <= maxLength) {
    98	    return text;
    99	  }
   100	  return text.slice(0, maxLength) + '...';
   101	}
   102	
   103	/**
   104	 * 防抖函数
   105	 */
   106	export function debounce<T extends (...args: any[]) => any>(
   107	  func: T,
   108	  wait: number
   109	): (...args: Parameters<T>) => void {
   110	  let timeout: NodeJS.Timeout;
   111	  
   112	  return (...args: Parameters<T>) => {
   113	    clearTimeout(timeout);
   114	    timeout = setTimeout(() => func(...args), wait);
   115	  };
   116	}
   117	
   118	/**
   119	 * 节流函数
   120	 */
   121	export function throttle<T extends (...args: any[]) => any>(
   122	  func: T,
   123	  limit: number
   124	): (...args: Parameters<T>) => void {
   125	  let inThrottle: boolean;
   126	  
   127	  return (...args: Parameters<T>) => {
   128	    if (!inThrottle) {
   129	      func(...args);
   130	      inThrottle = true;
   131	      setTimeout(() => (inThrottle = false), limit);
   132	    }
   133	  };
   134	}
