     8	interface RatingSectionProps {
     9	  novel: Novel;
    10	}
    11	
    12	export default function RatingSection({ novel }: RatingSectionProps) {
    13	  const { isAuthenticated } = useAuth();
    14	  const [userRating, setUserRating] = useState(0);
    15	  const [hoverRating, setHoverRating] = useState(0);
    16	  const [review, setReview] = useState('');
    17	  const [isSubmitting, setIsSubmitting] = useState(false);
    18	  const [showReviewForm, setShowReviewForm] = useState(false);
    19	
    20	  // 处理评分提交
    21	  const handleRatingSubmit = async () => {
    22	    if (!isAuthenticated) {
    23	      alert('请先登录');
    24	      return;
    25	    }
    26	
    27	    if (userRating === 0) {
    28	      alert('请选择评分');
    29	      return;
    30	    }
    31	
    32	    try {
    33	      setIsSubmitting(true);
    34	      await NovelService.rateNovel(novel.id, userRating, review || undefined);
    35	      alert('评分成功！');
    36	      setShowReviewForm(false);
    37	      setReview('');
    38	    } catch (error) {
    39	      console.error('Error submitting rating:', error);
    40	      alert('评分失败，请重试');
    41	    } finally {
    42	      setIsSubmitting(false);
    43	    }
    44	  };
    45	
    46	  // 渲染星星
    47	  const renderStars = (rating: number, interactive: boolean = false) => {
    48	    return Array.from({ length: 5 }, (_, i) => {
    49	      const starValue = i + 1;
    50	      const isFilled = starValue <= rating;
    51	      
    52	      return (
    53	        <button
    54	          key={i}
    55	          type="button"
    56	          disabled={!interactive}
    57	          className={`text-2xl transition-colors ${
    58	            interactive ? 'hover:scale-110 cursor-pointer' : 'cursor-default'
    59	          } ${isFilled ? 'text-yellow-500' : 'text-gray-300'}`}
    60	          onClick={() => interactive && setUserRating(starValue)}
    61	          onMouseEnter={() => interactive && setHoverRating(starValue)}
    62	          onMouseLeave={() => interactive && setHoverRating(0)}
    63	        >
    64	          ★
    65	        </button>
    66	      );
    67	    });
    68	  };
    69	
    70	  // 获取评分文本
    71	  const getRatingText = (rating: number): string => {
    72	    if (rating === 0) return '';
    73	    const texts = ['', '很差', '较差', '一般', '不错', '很好'];
    74	    return texts[rating] || '';
    75	  };
    76	
    77	  const currentRating = parseFloat(novel.rating) || 0;
    78	  const displayRating = hoverRating || userRating;
    79	
    80	  return (
    81	    <div className="bg-light-bg-secondary dark:bg-dark-bg-secondary 
    82	                    border border-light-border dark:border-dark-border 
    83	                    rounded-lg p-6 mb-8">
    84	      <h2 className="text-lg font-semibold text-light-text dark:text-dark-text mb-4">
    85	        读者评分
    86	      </h2>
    87	
    88	      <div className="flex flex-col lg:flex-row lg:items-start gap-6">
    89	        {/* 当前评分展示 */}
    90	        <div className="flex-1">
    91	          <div className="flex items-center space-x-4 mb-4">
    92	            <div className="text-center">
    93	              <div className="text-3xl font-bold text-light-text dark:text-dark-text">
    94	                {currentRating.toFixed(1)}
    95	              </div>
    96	              <div className="flex justify-center mb-1">
    97	                {renderStars(Math.round(currentRating))}
    98	              </div>
    99	              <div className="text-sm text-light-text-secondary dark:text-dark-text-secondary">
   100	                {novel.rating_count} 人评分
   101	              </div>
   102	            </div>
   103	            
   104	            {/* 评分分布（简化版） */}
   105	            <div className="flex-1 max-w-xs">
   106	              {[5, 4, 3, 2, 1].map((star) => (
   107	                <div key={star} className="flex items-center space-x-2 mb-1">
   108	                  <span className="text-sm text-light-text-secondary dark:text-dark-text-secondary w-8">
   109	                    {star}星
   110	                  </span>
   111	                  <div className="flex-1 bg-light-border dark:bg-dark-border rounded-full h-2">
   112	                    <div 
   113	                      className="bg-yellow-500 h-2 rounded-full"
   114	                      style={{ 
   115	                        width: `${Math.random() * 100}%` // 这里应该是真实的分布数据
   116	                      }}
   117	                    />
   118	                  </div>
   119	                </div>
   120	              ))}
   121	            </div>
   122	          </div>
   123	        </div>
   124	
   125	        {/* 用户评分区域 */}
   126	        <div className="lg:w-80">
   127	          {isAuthenticated ? (
   128	            <div className="border border-light-border dark:border-dark-border rounded-lg p-4">
   129	              <h3 className="text-md font-medium text-light-text dark:text-dark-text mb-3">
   130	                给这本书评分
   131	              </h3>
   132	              
   133	              <div className="flex items-center space-x-2 mb-3">
   134	                <div className="flex space-x-1">
   135	                  {renderStars(displayRating, true)}
   136	                </div>
   137	                {displayRating > 0 && (
   138	                  <span className="text-sm text-light-accent dark:text-dark-accent">
   139	                    {getRatingText(displayRating)}
   140	                  </span>
   141	                )}
   142	              </div>
   143	
   144	              {userRating > 0 && (
   145	                <div className="space-y-3">
   146	                  <button
   147	                    onClick={() => setShowReviewForm(!showReviewForm)}
   148	                    className="text-sm text-light-accent dark:text-dark-accent 
   149	                             hover:underline"
   150	                  >
   151	                    {showReviewForm ? '收起评价' : '写个评价'}
   152	                  </button>
   153	
   154	                  {showReviewForm && (
   155	                    <textarea
   156	                      value={review}
   157	                      onChange={(e) => setReview(e.target.value)}
   158	                      placeholder="分享你的阅读感受..."
   159	                      className="w-full p-3 border border-light-border dark:border-dark-border 
   160	                               rounded-md bg-light-bg dark:bg-dark-bg 
   161	                               text-light-text dark:text-dark-text 
   162	                               placeholder-light-text-secondary dark:placeholder-dark-text-secondary 
   163	                               focus:outline-none focus:ring-2 focus:ring-light-accent dark:focus:ring-dark-accent 
   164	                               resize-none"
   165	                      rows={3}
   166	                      maxLength={500}
   167	                    />
   168	                  )}
   169	
   170	                  <button
   171	                    onClick={handleRatingSubmit}
   172	                    disabled={isSubmitting}
   173	                    className="w-full px-4 py-2 bg-light-accent hover:bg-light-accent-hover 
   174	                             dark:bg-dark-accent dark:hover:bg-dark-accent-hover 
   175	                             text-white rounded-md transition-colors 
   176	                             disabled:opacity-50 disabled:cursor-not-allowed"
   177	                  >
   178	                    {isSubmitting ? '提交中...' : '提交评分'}
   179	                  </button>
   180	                </div>
   181	              )}
   182	            </div>
   183	          ) : (
   184	            <div className="border border-light-border dark:border-dark-border rounded-lg p-4 text-center">
   185	              <p className="text-light-text-secondary dark:text-dark-text-secondary mb-3">
   186	                登录后可以给小说评分
   187	              </p>
   188	              <button
   189	                onClick={() => {
   190	                  // 这里应该触发登录弹窗
   191	                  alert('请先登录');
   192	                }}
   193	                className="px-4 py-2 bg-light-accent hover:bg-light-accent-hover 
   194	                         dark:bg-dark-accent dark:hover:bg-dark-accent-hover 
   195	                         text-white rounded-md transition-colors"
   196	              >
   197	                立即登录
   198	              </button>
   199	            </div>
   200	          )}
   201	        </div>
   202	      </div>
   203	    </div>
   204	  );
   205	}
