    92	                     : 'bg-transparent border-light-accent dark:border-dark-accent text-light-accent dark:text-dark-accent hover:bg-light-accent hover:text-white dark:hover:bg-dark-accent dark:hover:text-white'
    93	                   }`}
    94	      >
